CREATE OR REPLACE FUNCTION public.guest_leave_by_phone(_event_id uuid, _phone text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE v_deleted integer; BEGIN IF auth.uid() IS NULL OR NOT EXISTS (SELECT 1 FROM public.match_events WHERE id=_event_id AND host_profile_id=public.my_profile_id()) THEN RAISE EXCEPTION 'Only the host can remove a guest by phone'; END IF; IF length(regexp_replace(coalesce(_phone,''),'\D','','g')) < 4 THEN RETURN false; END IF; DELETE FROM public.guest_participants WHERE match_event_id=_event_id AND regexp_replace(phone,'\D','','g')=regexp_replace(_phone,'\D','','g'); GET DIAGNOSTICS v_deleted=ROW_COUNT; RETURN v_deleted>0; END $$;
REVOKE ALL ON FUNCTION public.guest_leave_by_phone(uuid,text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.guest_leave_by_phone(uuid,text) TO authenticated, service_role;
DROP POLICY IF EXISTS "Users read qa_answers of their matches" ON public.qa_answers;
CREATE OR REPLACE FUNCTION public.get_pair_qa(_other uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_me uuid; BEGIN v_me:=public.my_profile_id(); IF v_me IS NULL THEN RAISE EXCEPTION 'not signed in'; END IF; RETURN jsonb_build_object('my_count',(SELECT count(*) FROM public.qa_answers WHERE profile_id=v_me),'their_count',(SELECT count(*) FROM public.qa_answers WHERE profile_id=_other),'rows',coalesce((SELECT jsonb_agg(jsonb_build_object('profile_id',profile_id,'question',question,'answer',answer)) FROM (SELECT profile_id,question,answer FROM public.qa_answers WHERE profile_id=v_me LIMIT 200) q),'[]'::jsonb)); END $$;
REVOKE ALL ON FUNCTION public.get_pair_qa(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.get_pair_qa(uuid) TO authenticated, service_role;
CREATE OR REPLACE FUNCTION public.is_safe_match_link(_url text) RETURNS boolean LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT coalesce(_url ~ '^https://(padelsetmatch\.com|www\.padelsetmatch\.com|padelmatchdoce\.com|www\.padelmatchdoce\.com|padelsetmatch\.lovable\.app|id-preview--cc494ba4-9302-4ef0-9a3b-7f1a472b1b7c\.lovable\.app)/(app/|m/|g/|play)([^[:space:]\\]*)$',false) $$;
ALTER TABLE public.short_links ADD CONSTRAINT short_links_safe_target CHECK (public.is_safe_match_link(target_url)) NOT VALID;
CREATE OR REPLACE FUNCTION public.can_read_current_photo(_path text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND EXISTS (SELECT 1 FROM public.profiles p WHERE p.photo_url IS NOT NULL AND (p.photo_url LIKE '%/padel-photos/' || _path || '?%' OR p.photo_url LIKE '%/padel-photos/' || _path) AND p.suspended_at IS NULL AND p.photo_moderation_status <> 'rejected' AND NOT EXISTS (SELECT 1 FROM public.blocks b WHERE (b.blocker_profile_id=public.my_profile_id() AND b.blocked_profile_id=p.id) OR (b.blocked_profile_id=public.my_profile_id() AND b.blocker_profile_id=p.id))) $$;
REVOKE ALL ON FUNCTION public.can_read_current_photo(text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.can_read_current_photo(text) TO authenticated;
DROP POLICY IF EXISTS "Authenticated read padel-photos" ON storage.objects;
CREATE POLICY "Read own or eligible current player photos" ON storage.objects FOR SELECT TO authenticated USING (bucket_id='padel-photos' AND ((storage.foldername(name))[1]=auth.uid()::text OR public.can_read_current_photo(name)));
ALTER TABLE public.profiles ADD COLUMN daily_question_answered_on date;
ALTER TABLE public.profiles DROP CONSTRAINT IF EXISTS profiles_gender_check;
ALTER TABLE public.profiles ADD CONSTRAINT profiles_gender_check CHECK (gender IN ('woman','man','non-binary','self-describe'));
CREATE OR REPLACE FUNCTION public.save_my_qa_answer(_question text,_category text,_answer text,_daily_date date DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_me uuid; v_id uuid; BEGIN SELECT id INTO v_me FROM public.profiles WHERE user_id=auth.uid() FOR UPDATE; IF v_me IS NULL THEN RAISE EXCEPTION 'Create your profile first'; END IF; IF length(trim(_question)) NOT BETWEEN 3 AND 400 OR length(trim(_answer)) NOT BETWEEN 1 AND 400 OR length(_category) NOT BETWEEN 1 AND 40 THEN RAISE EXCEPTION 'Invalid answer'; END IF; SELECT id INTO v_id FROM public.qa_answers WHERE profile_id=v_me AND question=_question ORDER BY created_at DESC LIMIT 1; IF v_id IS NULL THEN INSERT INTO public.qa_answers(profile_id,question,category,answer,answer_norm) VALUES(v_me,_question,_category,_answer,lower(trim(_answer))) RETURNING id INTO v_id; ELSE UPDATE public.qa_answers SET answer=_answer,answer_norm=lower(trim(_answer)),category=_category,created_at=now(),answer_embedding=NULL WHERE id=v_id; END IF; IF _daily_date IS NOT NULL THEN UPDATE public.profiles SET daily_question_answered_on=_daily_date WHERE id=v_me; END IF; DELETE FROM public.compatibility_scores WHERE profile_a=v_me OR profile_b=v_me; RETURN v_id; END $$;
REVOKE ALL ON FUNCTION public.save_my_qa_answer(text,text,text,date) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.save_my_qa_answer(text,text,text,date) TO authenticated;